DROP TABLE IF EXISTS `orvexa_product_customer`;
CREATE TABLE `orvexa_product_customer` (
  `product_customer_id` int NOT NULL AUTO_INCREMENT,
  `r_product_id` int NOT NULL,
  `r_customer_id` int NOT NULL,
  `is_deleted` enum('N','Y') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'N',
  PRIMARY KEY (`product_customer_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;


DROP TABLE IF EXISTS `orvexa_product_owners`;
CREATE TABLE `orvexa_product_owners` (
  `product_owners_id` int NOT NULL AUTO_INCREMENT,
  `r_product_id` int NOT NULL,
  `r_user_id` int NOT NULL,
  `created_date` datetime NOT NULL,
  `updated_date` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_owners_id`),
  UNIQUE KEY `unique_product_id` (`r_product_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

