DROP TABLE IF EXISTS `orvexa_product_user`;
CREATE TABLE `orvexa_product_user` (
  `product_user_id` int NOT NULL AUTO_INCREMENT,
  `r_product_id` int NOT NULL,
  `r_user_id` int NOT NULL,
  `r_role_id` int DEFAULT '8',
  `is_deleted` enum('N','Y') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'N',
  PRIMARY KEY (`product_user_id`),
  UNIQUE KEY `unique_product_user` (`r_product_id`,`r_user_id`),
  KEY `r_user_id` (`r_user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

