DROP TABLE IF EXISTS `orvexa_settings`;
CREATE TABLE `orvexa_settings` (
  `settings_id` int NOT NULL AUTO_INCREMENT,
  `settings_name` varchar(100) COLLATE utf8mb3_unicode_ci NOT NULL,
  `settings_value` int NOT NULL,
  `created_date` datetime NOT NULL,
  `updated_date` datetime NOT NULL ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`settings_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

