DROP TABLE IF EXISTS `orvexa_sprint`;
CREATE TABLE `orvexa_sprint` (
  `sprint_id` int NOT NULL AUTO_INCREMENT,
  `sprint_name` varchar(75) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `sprint_version` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `r_product_id` int DEFAULT NULL,
  `r_customer_id` int DEFAULT NULL,
  `r_sprint_duration_id` int DEFAULT NULL,
  `start_date` date DEFAULT NULL,
  `end_date` date DEFAULT NULL,
  `sprint_goal` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `r_module_status_id` int DEFAULT '19',
  `created_date` datetime DEFAULT NULL,
  `r_user_id_created` int DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `r_user_id_updated` int DEFAULT NULL,
  `estimated_hrs` tinyint NOT NULL DEFAULT '0',
  `is_deleted` enum('Y','N') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'N',
  PRIMARY KEY (`sprint_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

