DROP TABLE IF EXISTS `orvexa_user_action`;
CREATE TABLE `orvexa_user_action` (
  `action_id` int NOT NULL AUTO_INCREMENT,
  `r_user_id` int NOT NULL,
  `r_action_type_id` int NOT NULL,
  `r_product_id` int DEFAULT NULL,
  `r_module_id` int NOT NULL,
  `reference_id` int NOT NULL,
  `action_data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NOT NULL,
  `action_date` datetime DEFAULT NULL,
  `is_deleted` enum('N','Y') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'N',
  PRIMARY KEY (`action_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

