DROP TABLE IF EXISTS `orvexa_user_story`;
CREATE TABLE `orvexa_user_story` (
  `user_story_id` int NOT NULL AUTO_INCREMENT,
  `r_epic_id` int NOT NULL,
  `as_a_an` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `i_want` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `so_that` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `given` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `us_when` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `us_then` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `user_story_points` int DEFAULT NULL,
  `r_module_status_id` int NOT NULL,
  `estimated_hours` int DEFAULT NULL,
  `r_user_id_created` int NOT NULL,
  `r_user_id_updated` int NOT NULL,
  `created_date` datetime DEFAULT NULL,
  `updated_date` datetime DEFAULT NULL,
  `is_deleted` enum('N','Y') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'N',
  PRIMARY KEY (`user_story_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

INSERT INTO `orvexa_user_story` (`user_story_id`, `r_epic_id`, `as_a_an`, `i_want`, `so_that`, `given`, `us_when`, `us_then`, `user_story_points`, `r_module_status_id`, `estimated_hours`, `r_user_id_created`, `r_user_id_updated`, `created_date`, `updated_date`, `is_deleted`) VALUES
