DROP TABLE IF EXISTS `orvexa_user_story_condition`;
CREATE TABLE `orvexa_user_story_condition` (
  `condition_id` int NOT NULL AUTO_INCREMENT,
  `r_user_story_id` int NOT NULL,
  `condition_text` text CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci NOT NULL,
  `is_deleted` enum('N','Y') CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT 'N',
  PRIMARY KEY (`condition_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 COLLATE=utf8mb3_unicode_ci;

